GN['it.es'] = {
A1: [
 {t:'Los pronombres y los verbos essere y avere',
  b:`<p>Los pronombres sujeto son [[io]] (yo), [[tu]] (tú), [[lui]] / [[lei]] (él / ella), [[noi]] (nosotros), [[voi]] (vosotros), [[loro]] (ellos). El «usted» es [[Lei]].</p><div class="tblwrap"><table><tr><th></th><th>essere (ser / estar)</th><th>avere (tener / haber)</th></tr><tr><td>io</td><td>[[sono]]</td><td>[[ho]]</td></tr><tr><td>tu</td><td>[[sei]]</td><td>[[hai]]</td></tr><tr><td>lui / lei</td><td>[[è]]</td><td>[[ha]]</td></tr><tr><td>noi</td><td>[[siamo]]</td><td>[[abbiamo]]</td></tr><tr><td>voi</td><td>[[siete]]</td><td>[[avete]]</td></tr><tr><td>loro</td><td>[[sono]]</td><td>[[hanno]]</td></tr></table></div><p class="tip">Como en español, el pronombre se suele omitir: [[Sono stanco.]] = Estoy cansado. El italiano usa un solo verbo [[essere]] para «ser» y «estar». La h de avere no se pronuncia.</p>`,
  ex:['Soy estudiante.','Eres muy amable.','Tenemos un coche.','Ella tiene dos hijos.'],
  q:['«Estoy cansado»:','«Tenemos un gato»:']},
 {t:'El género y los artículos',
  b:`<p>Cada sustantivo es masculino (a menudo en -o) o femenino (a menudo en -a). El artículo definido depende del género y del primer sonido de la palabra:</p><div class="tblwrap"><table><tr><th></th><th>singular</th><th>plural</th></tr><tr><td>masculino</td><td>[[il libro]]; [[lo zaino]] (ante s + consonante, z); [[l'amico]]</td><td>[[i libri]]; [[gli zaini]], [[gli amici]]</td></tr><tr><td>femenino</td><td>[[la casa]]; [[l'isola]]</td><td>[[le case]]</td></tr></table></div><p>Indefinido: [[un libro]], [[uno zaino]], [[una mela]], [[un'amica]].</p><p class="tip">El plural cambia la vocal final y no añade -s: -o → -i, -a → -e, -e → -i: [[libro]] → [[libri]], [[casa]] → [[case]].</p>`,
  ex:['El libro es interesante.','La casa es grande.','Tengo un hermano y una hermana.','Los estudiantes estudian.'],
  q:['«la mochila» (zaino):','«una manzana» (mela):']},
 {t:'El presente: -are, -ere, -ire',
  b:`<p>Quita la terminación y añade:</p><div class="tblwrap"><table><tr><th></th><th>parlare</th><th>prendere</th><th>dormire</th></tr><tr><td>io</td><td>[[parlo]]</td><td>[[prendo]]</td><td>[[dormo]]</td></tr><tr><td>tu</td><td>[[parli]]</td><td>[[prendi]]</td><td>[[dormi]]</td></tr><tr><td>lui / lei</td><td>[[parla]]</td><td>[[prende]]</td><td>[[dorme]]</td></tr><tr><td>noi</td><td>[[parliamo]]</td><td>[[prendiamo]]</td><td>[[dormiamo]]</td></tr><tr><td>voi</td><td>[[parlate]]</td><td>[[prendete]]</td><td>[[dormite]]</td></tr><tr><td>loro</td><td>[[parlano]]</td><td>[[prendono]]</td><td>[[dormono]]</td></tr></table></div><p class="tip">Algunos verbos en -ire añaden -isc-: [[capire]] → [[capisco]], [[capisci]], [[capisce]], [[capiamo]], [[capite]], [[capiscono]].</p>`,
  ex:['Vivo en Roma.','¿Hablas italiano?','Tomamos un café.','Ellos duermen mucho.'],
  q:['«tú hablas» (parlare):','«nosotros escribimos» (scrivere):']},
 {t:'La negación y las preguntas',
  b:`<p>Se pone [[non]] delante del verbo, igual que «no» en español: [[Non parlo inglese.]]</p><p>La pregunta tiene el mismo orden que la afirmación y no lleva signo inicial: [[Parli italiano?]] Interrogativos: [[che cosa]] qué, [[chi]] quién, [[dove]] dónde, [[quando]] cuándo, [[come]] cómo, [[perché]] por qué, [[quanto]] cuánto.</p><p class="tip">«Me gusta» es [[mi piace]], exactamente como en español: [[Ti piace il tè?]] = ¿Te gusta el té?</p>`,
  ex:['No hablo inglés.','No tengo tiempo.','¿Te gusta el té?','¿Dónde vives?'],
  q:['«No como carne»:','«¿Cómo te llamas?»:']}
],
A2: [
 {t:'El passato prossimo con avere',
  b:`<p>El passato prossimo cuenta acciones terminadas (equivale al indefinido y al perfecto): [[avere]] en presente + participio: [[Ho mangiato.]] = Comí / He comido.</p><p>Participios: -are → [[-ato]] ([[parlato]]), -ere → [[-uto]] ([[venduto]]), -ire → [[-ito]] ([[dormito]]). Irregulares frecuentes: [[fatto]] (fare), [[preso]] (prendere), [[visto]] (vedere), [[letto]] (leggere), [[scritto]] (scrivere), [[detto]] (dire).</p>`,
  ex:['Comí una manzana.','Vimos una película.','¿Has terminado el trabajo?','Ella cogió el autobús.'],
  q:['«Compré un libro»:','«Hizo los deberes»:']},
 {t:'El passato prossimo con essere',
  b:`<p>A diferencia del español, los verbos de movimiento y cambio de estado, y todos los pronominales, usan [[essere]]: [[andare]], [[venire]], [[arrivare]], [[partire]], [[uscire]], [[restare]], [[nascere]], [[morire]], [[diventare]], [[alzarsi]].</p><p>Con essere el participio concuerda con el sujeto: [[Lui è andato.]] [[Lei è andata.]] [[Sono andati.]] [[Sono andate.]]</p>`,
  ex:['Fui al cine.','Ella llegó ayer.','Nos quedamos en casa.','Se fueron temprano.'],
  q:['«Ella vino»:','«Fuimos al mar»:']},
 {t:'Las preposiciones articuladas',
  b:`<p>Las preposiciones [[a]], [[da]], [[di]], [[in]], [[su]] se unen con el artículo, como «al» y «del» en español, pero con todas las formas:</p><div class="tblwrap"><table><tr><th></th><th>il</th><th>lo</th><th>la</th><th>l'</th><th>i</th><th>le</th></tr><tr><td>a</td><td>[[al]]</td><td>[[allo]]</td><td>[[alla]]</td><td>[[all']]</td><td>[[ai]]</td><td>[[alle]]</td></tr><tr><td>in</td><td>[[nel]]</td><td>[[nello]]</td><td>[[nella]]</td><td>[[nell']]</td><td>[[nei]]</td><td>[[nelle]]</td></tr><tr><td>su</td><td>[[sul]]</td><td>[[sullo]]</td><td>[[sulla]]</td><td>[[sull']]</td><td>[[sui]]</td><td>[[sulle]]</td></tr><tr><td>da</td><td>[[dal]]</td><td>[[dallo]]</td><td>[[dalla]]</td><td>[[dall']]</td><td>[[dai]]</td><td>[[dalle]]</td></tr><tr><td>di</td><td>[[del]]</td><td>[[dello]]</td><td>[[della]]</td><td>[[dell']]</td><td>[[dei]]</td><td>[[delle]]</td></tr></table></div><p class="tip">[[da]] también significa «en casa de»: [[dal medico]] = en el médico.</p>`,
  ex:['El libro está sobre la mesa.','Voy al supermercado.','Vuelvo de la oficina a las seis.','Las llaves están en el bolso.'],
  q:['«en el bolso» (la borsa):','«al mar» (il mare):']},
 {t:'Los adjetivos y la comparación',
  b:`<p>El adjetivo concuerda con el sustantivo y suele ir detrás: [[una gonna rossa]], [[due libri nuovi]]. Los adjetivos en -e tienen una sola forma: [[un uomo gentile]], [[una donna gentile]].</p><p>Algunos frecuentes van delante: [[bello]], [[buono]], [[grande]], [[piccolo]], [[nuovo]]: [[una bella casa]].</p><p>Comparación: [[più]] … [[di]] (más … que), [[meno]] … [[di]] (menos … que): [[Roma è più grande di Firenze.]] Superlativo: [[il più grande]]. Irregulares: [[buono]] → [[migliore]], [[cattivo]] → [[peggiore]].</p>`,
  ex:['Es una casa bonita.','Tiene los ojos verdes.','Roma es más grande que Florencia.','Es el mejor restaurante de la ciudad.'],
  q:['«una falda roja»:','«más grande que»:']}
],
B1: [
 {t:'El imperfetto y el passato prossimo',
  b:`<p>El imperfetto corresponde al pretérito imperfecto: describe el fondo, los hábitos y los estados: -are → [[-avo]], -ere → [[-evo]], -ire → [[-ivo]]: [[abitavo]], [[abitavi]], [[abitava]], [[abitavamo]], [[abitavate]], [[abitavano]]. Essere: [[ero]], [[eri]], [[era]]…</p><p>El passato prossimo cuenta lo que pasó. Juntos: [[Pioveva quando sono uscito.]] = Llovía cuando salí.</p><p class="tip">«Solía…» se dice con el imperfetto: [[Prima andavamo spesso al mare.]]</p>`,
  ex:['Cuando era pequeño, vivía en el campo.','Llovía cuando salí.','Antes íbamos a menudo al mar.'],
  q:['«De niño jugaba al fútbol»:','«Leía cuando sonó el teléfono»:']},
 {t:'Los pronombres complemento, ci y ne',
  b:`<p>Directos: [[lo]] (lo), [[la]] (la), [[li]] / [[le]] (los / las). Indirectos: [[gli]] (le, a él), [[le]] (le, a ella), [[gli]] (les). [[mi]], [[ti]], [[ci]], [[vi]] sirven para ambos.</p><p>Van delante del verbo: [[Lo vedo.]] [[Gli ho dato il libro.]]</p><p>[[ci]] sustituye un lugar (allí): [[Ci vado domani.]] [[ne]] sustituye «de eso, de ellos»: [[Ne voglio due.]] = Quiero dos.</p>`,
  ex:['Lo veo todos los días.','Le di el libro.','Voy allí mañana.'],
  q:['«La conozco»:','«Quiero dos (de ellos)»:']},
 {t:'El futuro y el condicional',
  b:`<p>Futuro simple: -are y -ere → [[-erò]], -ire → [[-irò]]: [[parlerò]], [[prenderò]], [[partirò]]; terminaciones [[-ò]], [[-ai]], [[-à]], [[-emo]], [[-ete]], [[-anno]]. Irregulares: [[sarò]] (essere), [[avrò]] (avere), [[andrò]], [[farò]], [[potrò]], [[verrò]].</p><p>Condicional: misma raíz + [[-ei]], [[-esti]], [[-ebbe]], [[-emmo]], [[-este]], [[-ebbero]]: [[vorrei]], [[partirei]], [[potrebbe]]. Petición cortés: [[Potrebbe aiutarmi?]] Consejo: [[Al posto tuo, partirei.]]</p>`,
  ex:['Mañana terminaré este trabajo.','Quisiera un café, por favor.','Yo que tú, me iría.'],
  q:['«Saldremos mañana»:','«¿Podría ayudarme?»:']}
],
B2: [
 {t:'El subjuntivo presente',
  b:`<p>Después de verbos de opinión, deseo, emoción y necesidad + [[che]] se usa el congiuntivo: [[Penso che tu abbia ragione.]] [[Voglio che tu sia felice.]]</p><p>-are → [[-i]]: [[che io parli]]; -ere / -ire → [[-a]]: [[che io prenda]], [[che io dorma]]. Irregulares: [[sia]] (essere), [[abbia]] (avere), [[faccia]], [[vada]], [[venga]], [[possa]].</p><p class="tip">Ojo: a diferencia del español, «creo que…» ([[penso che]], [[credo che]]) lleva subjuntivo en italiano.</p>`,
  ex:['Creo que tienes razón.','Quiero que seas feliz.','Es importante que vengan todos.'],
  q:['«Creo que es verdad»:','«Quiero que venga»:']},
 {t:'Los pronombres relativos: che, cui, il quale',
  b:`<p>[[che]] es sujeto o complemento directo: [[Il libro che leggo]], [[L'uomo che canta]].</p><p>Después de preposición se usa [[cui]]: [[la ragazza con cui parlo]], [[la città in cui sono nato]], [[il film di cui parlo]].</p><p class="tip">En estilo formal, [[il quale]] / [[la quale]] / [[i quali]] / [[le quali]] pueden sustituir a ambos, como «el cual».</p>`,
  ex:['El libro que leo es interesante.','La chica con la que hablo es mi hermana.','Es la ciudad en la que nací.'],
  q:['«El hombre que canta»:','«La película de la que hablo»:']},
 {t:'Las oraciones condicionales (periodo ipotetico)',
  b:`<p>Real: [[se]] + presente → presente / futuro: [[Se vieni, andiamo al parco.]]</p><p>Irreal en el presente: [[se]] + subjuntivo imperfecto → condicional, igual que en español: [[Se avessi tempo, viaggerei.]] Subjuntivo imperfecto: [[avessi]], [[fossi]], [[potessi]], [[parlassi]].</p><p>Irreal en el pasado: [[se]] + pluscuamperfecto de subjuntivo → condicional compuesto: [[Se l'avessi saputo, sarei venuto.]]</p><p class="tip">Nunca pongas el condicional después de [[se]].</p>`,
  ex:['Si tuviera tiempo, viajaría.','Si vienes, vamos al parque.','Si lo hubiera sabido, habría venido.'],
  q:['«Si fuera rico, compraría una casa»:','«Si lo hubiera sabido, habría venido»:']}
],
C1: [
 {t:'La pasiva y el si pasivo',
  b:`<p>La pasiva: [[essere]] + participio concordado: [[Il ponte è stato costruito nel 1900.]] En los tiempos simples se puede usar [[venire]] en lugar de essere: [[La decisione verrà presa domani.]]</p><p>El [[si]] impersonal / pasivo, como la pasiva refleja: [[Qui si parla italiano.]] = Aquí se habla italiano; [[In Italia si mangia bene.]] = En Italia se come bien.</p>`,
  ex:['El puente fue construido en 1900.','La decisión se tomará mañana.','En Italia se come bien.'],
  q:['«La carta fue enviada»:','«Aquí se habla italiano»:']},
 {t:'El gerundio',
  b:`<p>Gerundio: -are → [[-ando]], -ere / -ire → [[-endo]]: [[lavorando]], [[leggendo]], [[dormendo]]. Irregulares: [[facendo]], [[dicendo]], [[bevendo]].</p><p>[[stare]] + gerundio = acción en curso, como «estar + gerundio»: [[Sto lavorando.]] = Estoy trabajando.</p><p>Solo expresa simultaneidad, modo o causa: [[Ascolta la musica lavorando.]] [[Studiando, si impara molto.]]</p>`,
  ex:['Estoy trabajando.','Escucha música mientras trabaja.','Estudiando se aprende mucho.'],
  q:['«Estamos comiendo»:','«Leyendo se aprende»:']}
],
C2: [
 {t:'El passato remoto',
  b:`<p>El passato remoto es el pasado de la literatura y la historia (y del habla diaria en partes del sur de Italia). Describe hechos terminados y lejanos.</p><p>-are: [[-ai]], [[-asti]], [[-ò]], [[-ammo]], [[-aste]], [[-arono]]; -ere: [[-ei]], [[-é]], [[-erono]]; -ire: [[-ii]], [[-ì]], [[-irono]]. Muchos irregulares: [[fu]] (essere), [[ebbe]] (avere), [[fece]], [[nacque]], [[visse]], [[si sedette]].</p>`,
  ex:['Entró en la habitación y se sentó.','Dante nació en Florencia.','Vivieron felices y comieron perdices.'],
  q:['«él fue» (essere):','«ellos hicieron» (fare):']},
 {t:'El subjuntivo tras conjunciones y la concordancia de tiempos',
  b:`<p>Algunas conjunciones exigen siempre el subjuntivo: [[benché]] / [[sebbene]] (aunque), [[affinché]] (para que), [[prima che]] (antes de que), [[a meno che]] (a menos que), [[purché]] (con tal de que): [[Benché sia stanco, continua.]]</p><p>Si el verbo principal está en pasado, la subordinada va en subjuntivo imperfecto: [[Penso che sia a casa.]] → [[Pensavo che fosse a casa.]]</p>`,
  ex:['Aunque está cansado, sigue.','Te lo digo para que lo sepas.','Pensaba que estaba en casa.'],
  q:['«Aunque está enferma, trabaja»:','«Creía que vendría»:']}
]};
